def parse_kv_args(argv):
    result = {}
    i = 0

    while i < len(argv):
        arg = argv[i]

        if not arg.startswith("--"):
            i += 1
            continue

        key = arg[2:]

        if i + 1 < len(argv) and not argv[i + 1].startswith("--"):
            result[key] = argv[i + 1]
            i += 2
        else:
            result[key] = True
            i += 1

    return result
