import time

class TTLCache:
    def __init__(self):
        self._data = {}

    def set(self, key, value, ttl):
        self._data[key] = (value, time.time() + ttl)

    def get(self, key):
        item = self._data.get(key)
        if item is None:
            return None

        value, expires_at = item
        if time.time() >= expires_at:
            del self._data[key]
            return None

        return value
